<?php namespace App\Filament\Resources\PreventionCouncilResource\RelationManagers;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\RelationManagers\RelationManager;use Filament\Resources\Table;use Filament\Tables;use Illuminate\Support\Facades\DB;class CasesRelationManager extends RelationManager{protected static string $relationship='cases';protected static ?string $title='Рассматриваемые случаи';public static function form(Form $f):Form{return $f->schema([Forms\Components\Select::make('student_support_case_id')->label('Случай сопровождения')->options(fn()=>DB::table('student_support_cases as c')->join('students as s','s.id','=','c.student_id')->where('c.status','!=','closed')->select('c.id','c.reason','s.last_name','s.first_name')->get()->mapWithKeys(fn($x)=>[$x->id=>trim($x->last_name.' '.$x->first_name).' — '.$x->reason]))->searchable()->required(),Forms\Components\Textarea::make('decision')->label('Решение')->required(),Forms\Components\DatePicker::make('control_on')->label('Контрольная дата')]);}public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('student_support_case_id')->label('Студент')->formatStateUsing(function($id){$x=DB::table('student_support_cases as c')->join('students as s','s.id','=','c.student_id')->where('c.id',$id)->select('s.last_name','s.first_name')->first();return $x?trim($x->last_name.' '.$x->first_name):'—';}),Tables\Columns\TextColumn::make('decision')->label('Решение')->limit(80),Tables\Columns\TextColumn::make('control_on')->label('Контроль')->date('d.m.Y')])->headerActions([Tables\Actions\CreateAction::make()->label('Добавить случай')])->actions([Tables\Actions\EditAction::make(),Tables\Actions\DeleteAction::make()]);}}